# Gradient check: is every family's Stan gradient finite, and right, out in
# the tails?
#
# The R-versus-Stan tests compare *values*, and a value can be finite while
# its gradient is not: the LNR's log_mix() stayed finite with one component at
# -inf, but reverse mode multiplied the zero adjoint into an infinite partial,
# and one 5 s trial turned the gradient of the whole model to NaN. Only a
# compiled program with model methods sees that, which is what this script
# builds - one per family, generated by brms exactly as brm() would - and then
# it walks a grid of parameter points and asks two questions at each:
#
#   1. is grad_log_prob() finite wherever log_prob() is?
#   2. does it agree with central differences of log_prob()?
#
# A point where log_prob() itself is -inf is skipped (a legitimately impossible
# parameter value for these data), and counted. The grid is the starting value
# cogmod_inits() gives the model (or 0 on the unconstrained scale for the
# families it does not know), that point moved by +-`delta` along each
# unconstrained coordinate in turn, and `random` draws around it. Moving a
# scale parameter down by 2.5 on the softplus scale takes a sigma of 0.5 to
# about 0.05, which puts a 6 s trial some 80 standardized units out - the
# regime the erfc-based tails used to die in.
#
# Run from the repository root; every option has a default:
#
#   Rscript benchmarks/gradient_check.R
#   Rscript benchmarks/gradient_check.R --families cogmod_lnr,cogmod_ddm --cores 4
#
#   --pkg       working tree to load (default ".")
#   --out       output directory (default benchmarks/results/gradient_check)
#   --families  comma-separated subset (default: all)
#   --n         simulated trials per family before the tail responses (300)
#   --delta     step along each unconstrained coordinate (2.5)
#   --random    random points around the start (5)
#   --cores     families checked in parallel (1; ignored on Windows)
#   --tol       relative tolerance against central differences (1e-4)
#
# Exit status is 1 if any family fails, so CI can gate on it. Results go to
# <out>/gradient_check.csv (one row per family x point) and <out>/summary.md.
#
# A family listed in `.GP_KNOWN` below is allowed to fail the finite-difference
# comparison: its failures are reported as "known" and do not fail the job,
# only a *new* family failing does. Each entry carries the measured state and
# the cause, so that the entry is removed when the cause is; the script says
# so when a known family passes clean.

source("benchmarks/gradient_programs.R")

# Families whose gradient is known to disagree with central differences, with
# the reason. Non-finite gradients are never waived - only the mismatch is.
.GP_KNOWN <- c(
  # Stan's std_normal_lcdf() has exact values but approximate partial
  # derivatives, and cogmod_rdm() takes every normal tail through it. Measured
  # 2026-09-18: gradient 2e-4 relative from central differences at the start,
  # up to 7e-2 where the drift is small. The value itself is smooth to 1e-7.
  # Confirmed the same day by substitution: with cogmod_log_Phi()
  # (core_shifted.R) in place of all eleven calls, the worst error over the
  # same grid is 1.8e-7, at 9% more per gradient. That is the fix; it wants
  # cogmod_log_Phi() in a prelude the RDM can share.
  cogmod_rdm = "std_normal_lcdf() partials are approximate (2e-4 to 7e-2 relative)",
  # Stan's 7-parameter wiener_lpdf(): with both a start-point range and a
  # non-decision-time range, and the latter pushed wide (st0 = 0.46 s at
  # ndt = 0.035 s), the partials for `bias` and `sigmabias` come out 20 times
  # the one-sided slopes of the (smooth) value; every other point and partial
  # agrees to 1e-5. A Stan Math matter; measured 2026-09-18.
  cogmod_ddm = "wiener_lpdf() partials for w and sw are wrong at a wide st0"
)

opt <- gp_args(list(pkg = ".", out = "benchmarks/results/gradient_check",
                    families = "", n = 300L, delta = 2.5, random = 5L,
                    cores = 1L, tol = 1e-4))
gp_load(opt$pkg)
suppressPackageStartupMessages(library(cmdstanr))

fams <- if (nzchar(opt$families)) strsplit(opt$families, ",")[[1]] else gp_families()
unknown <- setdiff(fams, gp_families())
if (length(unknown)) stop("not a cogmod family: ", paste(unknown, collapse = ", "))

cat("Emitting programs\n")
emitted <- gp_emit(file.path(opt$out, "programs"), fams, n = opt$n, extremes = TRUE)

# ---- Evaluate ----------------------------------------------------------------
# The points, in unconstrained space, around `up0`.
#
# `up0` is first nudged off itself by a little fixed-seed noise. Starting
# values sit on round numbers - a bias of exactly 0.5, a drift of exactly 0 -
# and a density can have a kink there that is nowhere else: the DDM's
# start-point range is sigmabias * fmin(2w, 2(1 - w)), whose two arms tie at
# w = 0.5, so autodiff takes one arm (a different one for each boundary, since
# the lower one is scored with 1 - w) while central differences straddle the
# tie and report the average. Both are right, neither is the other, and no
# sampler ever sits at exactly 0.5. A quarter of a percent off is enough.
grid_points <- function(up0, delta, random, seed = 1) {
  P <- length(up0)
  set.seed(seed)
  up0 <- up0 + stats::rnorm(P, 0, 0.05)
  pts <- list(start = up0)
  for (j in seq_len(P)) {
    e <- replace(numeric(P), j, delta)
    pts[[sprintf("coord%d+", j)]] <- up0 + e
    pts[[sprintf("coord%d-", j)]] <- up0 - e
  }
  for (r in seq_len(random)) pts[[sprintf("random%d", r)]] <- up0 + stats::rnorm(P, 0, 0.75)
  pts
}

# Compile and evaluate one family. Model methods have to be compiled in the
# process that uses them (cmdstanr refuses them on an executable it merely
# finds on disk), so the compilation lives here rather than in a stage of its
# own, and this whole function is what gets parallelised.
check_family <- function(row) {
  fam <- row$family
  mod <- gp_compile(row$stan)
  m <- gp_methods(mod, row$data, row$init)
  fit <- m$fit
  pts <- grid_points(m$up0, opt$delta, opt$random)
  h <- 1e-5
  rows <- lapply(names(pts), function(nm) {
    up <- pts[[nm]]
    lp <- tryCatch(fit$log_prob(up, jacobian = TRUE), error = function(e) NaN)
    if (!is.finite(lp)) {
      return(data.frame(family = fam, point = nm, lp = lp, grad_finite = NA,
                        fd_err = NA_real_, status = if (is.nan(lp)) "lp_nan" else "lp_inf",
                        stringsAsFactors = FALSE))
    }
    g <- tryCatch(as.numeric(fit$grad_log_prob(up, jacobian = TRUE)),
                  error = function(e) rep(NaN, length(up)))
    if (!all(is.finite(g))) {
      return(data.frame(family = fam, point = nm, lp = lp, grad_finite = FALSE,
                        fd_err = NA_real_, status = "grad_nonfinite",
                        stringsAsFactors = FALSE))
    }
    fd <- vapply(seq_along(up), function(j) {
      e <- replace(numeric(length(up)), j, h)
      (fit$log_prob(up + e, jacobian = TRUE) - fit$log_prob(up - e, jacobian = TRUE)) / (2 * h)
    }, numeric(1))
    # Relative to the finite difference, with a floor of 1 and an allowance for
    # the finite differences' own rounding, which grows with |lp|.
    err <- max(abs(g - fd) / pmax(1, abs(fd)))
    ok <- all(abs(g - fd) <= opt$tol * pmax(1, abs(fd)) + 1e-9 * abs(lp))
    data.frame(family = fam, point = nm, lp = lp, grad_finite = TRUE, fd_err = err,
               status = if (ok) "ok" else "grad_mismatch", stringsAsFactors = FALSE)
  })
  do.call(rbind, rows)
}

run_family <- function(i) {
  row <- emitted[i, ]
  tryCatch(check_family(row), error = function(e) {
    data.frame(family = row$family, point = NA, lp = NA, grad_finite = NA, fd_err = NA,
               status = paste("error:", conditionMessage(e)), stringsAsFactors = FALSE)
  })
}

cores <- if (.Platform$OS.type == "windows") 1L else max(1L, opt$cores)
cat("Compiling and evaluating", nrow(emitted), "programs")
if (cores > 1) cat(" on", cores, "cores")
cat("\n")
t0 <- Sys.time()
results <- if (cores > 1) {
  parallel::mclapply(seq_len(nrow(emitted)), run_family, mc.cores = cores)
} else {
  lapply(seq_len(nrow(emitted)), run_family)
}
cat(sprintf("  %.0f s\n", as.numeric(Sys.time() - t0, units = "secs")))
for (res in results) {
  n_ok <- sum(res$status == "ok")
  n_skip <- sum(res$status == "lp_inf")
  is_known <- res$status == "grad_mismatch" & res$family[1] %in% names(.GP_KNOWN)
  n_known <- sum(is_known)
  n_bad <- nrow(res) - n_ok - n_skip - n_known
  cat(sprintf("  %-22s %2d ok, %2d skipped (lp = -inf), %2d known, %2d FAILED%s\n", res$family[1],
              n_ok, n_skip, n_known, n_bad,
              if (n_bad) paste0("  <- ", paste(unique(res$status[!res$status %in% c("ok", "lp_inf") & !is_known]), collapse = ", ")) else ""))
}
results <- do.call(rbind, results)
utils::write.csv(results, file.path(opt$out, "gradient_check.csv"), row.names = FALSE)

# ---- Summary -----------------------------------------------------------------
# A mismatch in a family listed in .GP_KNOWN is "known"; anything else that is
# not ok or a legitimate -inf is a failure.
bad <- results$status != "ok" & results$status != "lp_inf"
known <- bad & results$status == "grad_mismatch" & results$family %in% names(.GP_KNOWN)
new_bad <- bad & !known
per <- do.call(rbind, lapply(split(results, results$family), function(r) {
  b <- r$status != "ok" & r$status != "lp_inf"
  k <- b & r$status == "grad_mismatch" & r$family[1] %in% names(.GP_KNOWN)
  data.frame(family = r$family[1],
             points = nrow(r),
             ok = sum(r$status == "ok"),
             skipped = sum(r$status == "lp_inf"),
             failed = sum(b & !k),
             known = sum(k),
             max_fd_err = if (any(is.finite(r$fd_err))) max(r$fd_err, na.rm = TRUE) else NA_real_,
             note = if (any(b & !k)) paste(unique(r$status[b & !k]), collapse = "; ")
                    else if (any(k)) unname(.GP_KNOWN[r$family[1]])
                    else if (r$family[1] %in% names(.GP_KNOWN)) "passes clean: drop its .GP_KNOWN entry"
                    else "",
             stringsAsFactors = FALSE)
}))
verdict <- if (any(new_bad)) "FAILED" else if (any(known)) "passed (known mismatches only)" else "passed"
md <- c(
  sprintf("## Gradient check: %s", verdict),
  "",
  sprintf("%d families, %d points; %d failed, %d known mismatches, %d skipped where log_prob is -inf.",
          nrow(per), nrow(results), sum(new_bad), sum(known), sum(results$status == "lp_inf")),
  "",
  "| family | points | ok | skipped | failed | known | max rel. error vs central differences | note |",
  "|---|---:|---:|---:|---:|---:|---:|---|",
  sprintf("| %s | %d | %d | %d | %d | %d | %s | %s |", per$family, per$points, per$ok, per$skipped,
          per$failed, per$known,
          ifelse(is.na(per$max_fd_err), "", formatC(per$max_fd_err, format = "e", digits = 1)),
          per$note)
)
writeLines(md, file.path(opt$out, "summary.md"))
cat("\n", paste(md, collapse = "\n"), "\n", sep = "")

if (any(new_bad)) {
  cat("::error::gradient check failed for", paste(unique(results$family[new_bad]), collapse = ", "), "\n")
  quit(status = 1)
}
